"""LLM 提示词构造与输出解析（SFT / 生成 / DPO 共用，保证训练与推理格式一致）"""
import json
import re

import numpy as np
import pandas as pd

PRIMARY = ["dst_port", "protocol", "flow_duration", "fwd_pkts", "bwd_pkts", "fwd_bytes", "bwd_bytes"]

CLASS_DESC = {
    "Benign": "normal, legitimate user traffic",
    "DDoS-HOIC": "HTTP flood DDoS generated by the HOIC tool against a web server (port 80)",
    "DDoS-LOIC-UDP": "UDP flood DDoS generated by the LOIC tool",
    "DDoS-LOIC-HTTP": "HTTP flood DDoS generated by the LOIC tool",
    "FTP-BruteForce": "password brute-force login attempts against an FTP server (port 21) with Patator",
    "SSH-BruteForce": "password brute-force login attempts against an SSH server (port 22) with Patator",
    "Web-BruteForce": "brute-force login attempts against a web application login form over HTTP",
    "Web-XSS": "cross-site scripting payload injection against a web application over HTTP",
    "Web-SQLi": "SQL injection requests against a web application over HTTP",
    "Infiltration": "post-compromise internal reconnaissance and lateral movement from an infected host",
    "Bot": "botnet command-and-control traffic",
    "PortScan": "port scanning probes",
    # CIC-IDS2017（只新增键，不影响 CSE / NF 的提示）
    "Heartbleed": "OpenSSL Heartbleed exploitation over TLS (port 444) leaking server memory in long sessions",
    "DDoS": "DDoS flood against a web server generated by the LOIC tool",
    "DoS Hulk": "HTTP GET flood DoS generated by the HULK tool against a web server",
    "DoS GoldenEye": "HTTP keep-alive flood DoS generated by the GoldenEye tool",
    "DoS slowloris": "slow HTTP header DoS (slowloris) keeping many web connections open",
    "DoS Slowhttptest": "slow HTTP body/read DoS generated by slowhttptest",
    # UNSW-NB15（NetFlow 版本）
    "Exploits": "exploitation of known software vulnerabilities on a target host",
    "Fuzzers": "fuzzing that sends randomised malformed input to crash or probe a service",
    "Generic": "generic attacks against block ciphers / cryptographic implementations",
    "Reconnaissance": "reconnaissance probing and information gathering about hosts and services",
    "DoS": "denial-of-service attempts that exhaust a service or host",
    "Backdoor": "traffic of a backdoor that bypasses authentication to give remote access",
    "Shellcode": "small payloads of shellcode delivered to exploit a vulnerability",
    "Analysis": "port scans, spam and HTML-file penetration analysis activity",
    "Worms": "self-replicating worm traffic spreading to other hosts",
}

FIELD_DOC = (
    "dst_port: destination port (0-65535); "
    "protocol: IANA protocol number (6=TCP, 17=UDP, 1=ICMP, 0=HOPOPT); "
    "flow_duration: flow duration in microseconds; "
    "fwd_pkts / bwd_pkts: number of packets in forward / backward direction; "
    "fwd_bytes / bwd_bytes: total payload bytes in forward / backward direction "
    "(average payload per packet cannot exceed 65535; a flow has at least one packet)."
)

SYSTEM = ("You are a network traffic simulator for intrusion-detection research. "
          "You output exactly one realistic bidirectional flow record as a single-line JSON object and nothing else.")


def row_json(r) -> str:
    return json.dumps({k: int(r[k]) for k in PRIMARY}, separators=(",", ":"))


def build_messages(label: str, shots: pd.DataFrame):
    desc = CLASS_DESC.get(label, label)
    ex = "\n".join(row_json(r) for _, r in shots.iterrows())
    user = (f"Traffic class: {label} — {desc}.\n"
            f"Fields: {FIELD_DOC}\n"
            f"Real examples of this class:\n{ex}\n"
            f"Generate ONE new, different but realistic {label} flow. "
            f"Do not copy an example. Output only JSON with exactly the keys {PRIMARY}.")
    return [{"role": "system", "content": SYSTEM}, {"role": "user", "content": user}]


_JSON = re.compile(r"\{[^{}]*\}")


def parse(text: str):
    """返回 (dict 或 None)。容错：取第一个 {...}，键名小写化，数值转 int"""
    m = _JSON.search(text or "")
    if not m:
        return None
    try:
        d = json.loads(m.group(0))
    except json.JSONDecodeError:
        return None
    d = {str(k).strip().lower(): v for k, v in d.items()}
    if not all(k in d for k in PRIMARY):
        return None
    out = {}
    for k in PRIMARY:
        try:
            out[k] = float(d[k])
        except (TypeError, ValueError):
            return None
    return out


def class_knn(df_c: pd.DataFrame, n_neighbors: int) -> np.ndarray:
    """同类样本在 log1p + 标准化空间中的近邻索引表；第 0 列为自身"""
    from sklearn.neighbors import NearestNeighbors
    L = np.log1p(df_c[PRIMARY].to_numpy(float))
    Z = (L - L.mean(0)) / (L.std(0) + 1e-9)
    kk = min(n_neighbors + 1, len(df_c))
    _, idx = NearestNeighbors(n_neighbors=kk).fit(Z).kneighbors(Z)
    return idx


def anchor_shots(df_c: pd.DataFrame, knn: np.ndarray, anchor: int, k: int, rng: np.random.Generator,
                 include_anchor: bool = True) -> pd.DataFrame:
    """锚点式示例：以一条真实样本为锚点，示例取锚点（可选）+ 其近邻（从最近的 2k 个中随机取），顺序打乱。
    相比随机抽 k 条同类样本，示例都来自同一局部形态，LLM 不会在多个形态之间“取平均”（见 v1 的模态丢失问题）。"""
    neigh = [int(j) for j in knn[anchor] if j != anchor]
    m = k - 1 if include_anchor else k
    m = min(m, len(neigh))
    cand = neigh[:max(2 * m, m)]
    pick = list(rng.permutation(cand)[:m]) if m > 0 else []
    rows = ([anchor] if include_anchor else []) + pick
    return df_c.iloc[list(rng.permutation(rows))]


def anchor_schedule(n_rows: int, n_prompts: int, rng: np.random.Generator) -> np.ndarray:
    """每条真实样本轮流作为锚点（多轮随机排列拼接），使各形态获得与真实数据成比例的提示数"""
    reps = int(np.ceil(n_prompts / max(1, n_rows)))
    return np.concatenate([rng.permutation(n_rows) for _ in range(reps)])[:n_prompts]


def sample_shots(df_c: pd.DataFrame, k: int, rng: np.random.Generator, exclude=None):
    pool = df_c if exclude is None else df_c.drop(index=exclude, errors="ignore")
    k = min(k, len(pool))
    return pool.iloc[rng.choice(len(pool), k, replace=False)]
